import random
from typing import List


def get_response(answers: List[str]) -> str:
    response = random.choice(answers)
    return response


def generate_json() -> dict:
    responses = ["I see myself as a chatbot who can be rigid", "I see myself as a chatbot who can be flexible"]
    score = random.randint(1, 5)

    return {"score": score, "response": get_response(responses)}
